configuration.script:
// Schaltet den GoodWe-Wechselrichter zwischen Netzladen und Automatik um.
// Entspricht:
//   EIN: 47512 = 3000 W, danach 47511 = 2 (Laden)
//   AUS: 47511 = 1 (Automatik), danach 47512 = 0
// Der Schalter selbst wird NICHT hier gesetzt, sondern nur durch die Regel
// "Netzladen Status", die den tatsaechlich gelesenen Modus anzeigt.
val ladeleistung = 3000

if (receivedCommand == ON) {
    Goodwe_EMS_Power.sendCommand(ladeleistung)
    Thread::sleep(300)
    Goodwe_EMS_Mode.sendCommand(2)
    logInfo("Netzladen", "Netzladen EIN angefordert: Mode 2, " + ladeleistung + " W")
} else {
    Goodwe_EMS_Mode.sendCommand(1)
    Thread::sleep(300)
    Goodwe_EMS_Power.sendCommand(0)
    logInfo("Netzladen", "Netzladen AUS angefordert: Mode 1 (Automatik), 0 W")
}

// Zeigt im Schalter immer den tatsaechlichen Zustand des Wechselrichters an.
// Register 47511 wird alle 2 Sekunden gelesen. Steht es auf 2 (Laden),
// ist der Schalter AN, sonst AUS - unabhaengig davon, was zuletzt geklickt wurde.
if (Goodwe_EMS_Mode.state instanceof Number) {
    val soll = if ((Goodwe_EMS_Mode.state as Number).intValue == 2) ON else OFF
    if (Goodwe_Netzladen.state != soll) {
        Goodwe_Netzladen.postUpdate(soll)
        logInfo("Netzladen", "Status vom Wechselrichter: EMS Mode " + Goodwe_EMS_Mode.state + " -> Schalter " + soll)
    }
}
